class Solution:
    def merge(self, nums1: list[int], m: int, nums2: list[int], n: int) -> None:
        for i in range(n):
            nums1[m+i] = nums2[i]
        for _ in range(m+n):
            for i in range(1, m+n):
                if nums1[i-1] > nums1[i]:
                    nums1[i-1], nums1[i] = nums1[i], nums1[i-1]

