class Solution:
    def merge(self, nums1: list[int], m: int, nums2: list[int], n: int) -> None:
        left = nums1[:m]
        i = j = k = 0
        while i < m and j < n:
            if left[i] <= nums2[j]:
                nums1[k] = left[i]; i += 1
            else:
                nums1[k] = nums2[j]; j += 1
            k += 1
        while i < m:
            nums1[k] = left[i]; i += 1; k += 1
        while j < n:
            nums1[k] = nums2[j]; j += 1; k += 1

